use std::borrow::Cow;
use std::marker::PhantomData;

use rustc_data_structures::inspect::{self, EnumVariant, Value};
use rustc_data_structures::stable_hasher::{HashStable, SpanArgs, StructureState};
use rustc_middle::ty::TyCtxt;
use rustc_middle::ty::print::with_no_trimmed_paths;
use rustc_query_system::ich::StableHashingContext;
use rustc_span::{CachingSourceMapView, Pos, Span};

// NOTE: `PER_QUERY_COLLECT_STRUCTURES_FNS` is generated by the query
// macro into the plumbing module; do not import it here.
use crate::PER_QUERY_COLLECT_STRUCTURES_FNS;
use std::fs;
use std::io::{ Write, Seek, SeekFrom};
use std::path::PathBuf;
use rustc_span::def_id::LOCAL_CRATE;
use brotli::CompressorWriter;
use brotli::enc::BrotliEncoderParams;

fn def_path_value<'tcx>(tcx: TyCtxt<'tcx>, crate_num: u32, index: u32) -> inspect::Value {
    // Construct a `DefId` from the supplied `u32` crate/def indices
    // and return an `inspect::Value::String` containing the def path.
    let def_id = rustc_span::def_id::DefId {
        krate: rustc_span::def_id::CrateNum::from_u32(crate_num),
        index: rustc_span::def_id::DefIndex::from_u32(index),
    };
    inspect::Value::String(with_no_trimmed_paths!(tcx.def_path_str(def_id).into()))
}

fn span_value(
    tcx: TyCtxt<'_>,
    span_args: SpanArgs,
    state: &mut StructureState<'_, StableHashingContext<'_>>,
) -> inspect::Value {
    let span = Span::from_args(span_args);

    let span = span.data_untracked();
    let ctx_val = span.ctxt.structure(state);
    let parent_val = span.parent.structure(state);

    if span.is_dummy() {
        return Value::Enum {
            path: std::borrow::Cow::Borrowed("Span"),
            variant: EnumVariant::Unit(std::borrow::Cow::Borrowed("Dummy")),
        };
    }

    let parent = span.parent.map(|parent| tcx.def_span(parent).data_untracked());
    if let Some(parent) = parent
        && parent.contains(span)
    {
        // This span is enclosed in a definition: only hash the relative position. This catches
        // a subset of the cases from the `file.contains(parent.lo)`. But we can do this check
        // cheaply without the expensive `span_data_to_lines_and_cols` query.
        let lo = (span.lo - parent.lo).to_u32();
        let hi = (span.hi - parent.lo).to_u32();
        return Value::Enum {
            path: Cow::Borrowed("Span"),
            variant: EnumVariant::Named(
                Cow::Borrowed("Relative"),
                vec![
                    (Cow::Borrowed("ctxt"), ctx_val),
                    (Cow::Borrowed("parent"), parent_val),
                    (Cow::Borrowed("lo"), lo.structure(state)),
                    (Cow::Borrowed("hi"), hi.structure(state)),
                ],
            ),
        };
    }

    let mut caching = CachingSourceMapView::new(tcx.sess.source_map());

    // If this is not an empty or invalid span, we want to hash the last position that belongs
    // to it, as opposed to hashing the first position past it.
    let Some((file, line_lo, col_lo, line_hi, col_hi)) = caching.span_data_to_lines_and_cols(&span)
    else {
        return Value::Enum {
            path: std::borrow::Cow::Borrowed("Span"),
            variant: EnumVariant::Unit(std::borrow::Cow::Borrowed("Dummy")),
        };
    };

    if let Some(parent) = parent
        && file.contains(parent.lo)
    {
        // This span is relative to another span in the same file,
        // only hash the relative position.
        let lo = span.lo.0.wrapping_sub(parent.lo.0);
        let hi = span.hi.0.wrapping_sub(parent.lo.0);
        return Value::Enum {
            path: Cow::Borrowed("Span"),
            variant: EnumVariant::Named(
                Cow::Borrowed("Relative"),
                vec![
                    (Cow::Borrowed("ctxt"), ctx_val),
                    (Cow::Borrowed("parent"), parent_val),
                    (Cow::Borrowed("lo"), lo.structure(state)),
                    (Cow::Borrowed("hi"), hi.structure(state)),
                ],
            ),
        };
    }

    // Hash both the length and the end location (line/column) of a span. If we hash only the
    // length, for example, then two otherwise equal spans with different end locations will
    // have the same hash. This can cause a problem during incremental compilation wherein a
    // previous result for a query that depends on the end location of a span will be
    // incorrectly reused when the end location of the span it depends on has changed (see
    // issue #74890). A similar analysis applies if some query depends specifically on the
    // length of the span, but we only hash the end location. So hash both.
    let len = (span.hi - span.lo).0;

    Value::Enum {
        path: Cow::Borrowed("Span"),
        variant: EnumVariant::Named(
            Cow::Borrowed("Valid"),
            vec![
                (Cow::Borrowed("ctxt"), ctx_val),
                (Cow::Borrowed("parent"), parent_val),
                (Cow::Borrowed("stable_id"), file.stable_id.structure(state)),
                (Cow::Borrowed("col_lo"), col_lo.structure(state)),
                (Cow::Borrowed("col_hi"), col_hi.structure(state)),
                (Cow::Borrowed("line_lo"), line_lo.structure(state)),
                (Cow::Borrowed("line_hi"), line_hi.structure(state)),
                (Cow::Borrowed("len"), len.structure(state)),
            ],
        ),
    }
}

/// Collects structural representations for all queries and returns
/// them as an inspect::Value map: query_name -> { key -> value }
pub(crate) fn collect_all_query_structures<'tcx>(
    tcx: TyCtxt<'tcx>,
    // Optional file to which per-query compressed payloads will be written as
    // we iterate over PER_QUERY_COLLECT_STRUCTURES_FNS. We need Seek to
    // obtain current offsets. If `None` is passed, we will not write payloads
    // but instead hash each per-query `Map` value and store that hash.
    mut file: Option<&mut fs::File>,
) -> Result<inspect::Value, ()> {
    let mut state = StructureState::<'_, StableHashingContext<'_>> {
        def_path: &|crate_num, index| def_path_value(tcx, crate_num, index),
        span_value: &|args, state| span_value(tcx, args, state),
        _marker: PhantomData,
    };

    let mut out: Vec<(inspect::Value, inspect::Value)> = Vec::new();

    use std::hash::Hash;
    use rustc_hashes::Hash128;
    use rustc_data_structures::stable_hasher::StableHasher;

    for f in PER_QUERY_COLLECT_STRUCTURES_FNS.iter() {
        let (name, map) = f(tcx, &mut state);
        // If the map is a Map of entries for this query, either serialize and
        // compress it and write it to `file` (when file is Some) or compute a
        // stable hash of the `map` (when file is None) and store that instead
        // of the payload offset.
        let value_to_store = if let inspect::Value::Map(_) = &map {
            if let Some(file) = file.as_deref_mut() {
                // Serialize
                let ser = match bincode::serialize(&map) {
                    Ok(b) => b,
                    Err(_) => return Err(()),
                };

                // Compress into memory
                let mut compressed: Vec<u8> = Vec::new();
                let params = BrotliEncoderParams::default();
                {
                    let mut compressor = CompressorWriter::with_params(&mut compressed, 4096, &params);
                    if compressor.write_all(&ser).is_err() {
                        return Err(());
                    }
                }

                // Obtain current offset in file and write compressed bytes.
                let offset = match file.seek(SeekFrom::Current(0)) {
                    Ok(o) => o,
                    Err(_) => return Err(()),
                };
                if file.write_all(&compressed).is_err() {
                    return Err(());
                }

                inspect::Value::UInt(offset as u128)
            } else {
                // No file provided: compute a stable 128-bit hash of the
                // inspect::Value map and store it as a UInt.
                let mut hasher = StableHasher::new();
                map.hash(&mut hasher);
                let h = hasher.finish::<Hash128>();
                inspect::Value::UInt(h.as_u128())
            }
        } else {
            map
        };

        out.push((inspect::Value::String(name.into()), value_to_store));
    }

    // Convert Vec into BTreeMap for the Map variant
    let mut entries_map: ::std::collections::BTreeMap<inspect::Value, inspect::Value> =
        ::std::collections::BTreeMap::new();
    for (k, v) in out.into_iter() {
        entries_map.insert(k, v);
    }

    Ok(inspect::Value::Map(entries_map))
}

// Module-scoped helper for exporting query structures when the feature is enabled.
pub(crate) fn export_queries_if_enabled<'tcx>(tcx: TyCtxt<'tcx>) {
    // Check option enablement on the unstable options struct.
    if !tcx.sess.opts.unstable_opts.export_queries {
        return;
    }

    let dir = match &tcx.sess.opts.unstable_opts.export_queries_dir {
        Some(d) => d.clone(),
        None => return,
    };

    // Determine crate name/hash early so the directory scanning can use them.
    let crate_name = tcx.crate_name(LOCAL_CRATE).to_string();
    let crate_hash = if tcx.needs_crate_hash() {
        tcx.crate_hash(LOCAL_CRATE).to_hex()
    } else {
        "no-hash".to_string()
    };

    // Ensure directory exists; if creation fails, emit a warning diagnostic.
    if let Err(e) = fs::create_dir_all(&dir) {
        tcx.sess.dcx().emit_warn(crate::error::ExportQueriesCreateDirFail {
            path: dir.as_path(),
            err: e.to_string(),
        });
        return;
    }

    // Scan existing files to determine next dedup number.
    let mut max_dedup = 0usize;
    if let Ok(read_dir) = fs::read_dir(&dir) {
        for entry in read_dir.flatten() {
            let path = entry.path();
            if let Some(fname) = path.file_name().and_then(|s| s.to_str()) {
                let prefix = format!("{}.{}.", crate_name, crate_hash);
                if fname.starts_with(&prefix) {
                    if let Some(s) = fname.rsplit('.').next() {
                        if let Ok(n) = s.parse::<usize>() {
                            if n >= max_dedup {
                                max_dedup = n + 1
                            }
                        }
                    }
                }
            }
        }
    }

    let dedup = max_dedup;
    let filename = format!("{}.{}.{}", crate_name, crate_hash, dedup);
    let mut path = PathBuf::from(&dir);
    path.push(&filename);

    // Create the file to stream payloads into.
    let mut f = match fs::File::create(&path) {
        Ok(file) => file,
        Err(e) => {
            tcx.sess.dcx().emit_warn(crate::error::ExportQueriesFileWriteFail {
                path: path.as_path(),
                err: e.to_string(),
            });
            return;
        }
    };

    // Collect and stream per-query payloads into `f`. This will write the
    // compressed per-query payloads and return a top-level `Value` where
    // those entries have been replaced with their offsets.
        let value = match collect_all_query_structures(tcx, Some(&mut f)) {
            Ok(v) => v,
            Err(_) => return,
        };

    // Now write the serialized top-level Value and footer.
    let pos_main = match f.seek(SeekFrom::Current(0)) {
        Ok(p) => p,
        Err(_) => return,
    };

    let bytes = match bincode::serialize(&value) {
        Ok(b) => b,
        Err(_) => return,
    };

    if f.write_all(&bytes).is_err() {
        tcx.sess.dcx().emit_warn(crate::error::ExportQueriesFileWriteFail {
            path: path.as_path(),
            err: "failed to write top-level value".to_string(),
        });
        return;
    }

    if f.write_all(&pos_main.to_le_bytes()).is_err() {
        tcx.sess.dcx().emit_warn(crate::error::ExportQueriesFileWriteFail {
            path: path.as_path(),
            err: "failed to write footer".to_string(),
        });
        return;
    }

    // The remainder of the function finishes above (file creation, streaming,
    // writing top-level value and footer). No further actions needed here.
}

/// Assemble the final per-query structure map from the entries and metadata.
pub(crate) fn assemble_query_structures<K, V>(
    name: String,
    entries_map: ::std::collections::BTreeMap<inspect::Value, inspect::Value>,
) -> (String, inspect::Value)
where
    K: Sized,
    V: Sized,
{
    let key_type_name = std::any::type_name::<K>();
    let value_type_name = std::any::type_name::<V>();
    let key_size = std::mem::size_of::<K>();
    let value_size = std::mem::size_of::<V>();

    let mut out_map: Vec<(inspect::Value, inspect::Value)> = Vec::new();
    out_map.push((inspect::Value::String("entries".into()), inspect::Value::Map(entries_map)));
    out_map.push((inspect::Value::String("key_type".into()), inspect::Value::String(key_type_name.into())));
    out_map.push((inspect::Value::String("value_type".into()), inspect::Value::String(value_type_name.into())));
    out_map.push((inspect::Value::String("key_size".into()), inspect::Value::UInt(key_size as u128)));
    out_map.push((inspect::Value::String("value_size".into()), inspect::Value::UInt(value_size as u128)));

    // Convert out_map Vec to BTreeMap before returning
    let mut ret_map: ::std::collections::BTreeMap<inspect::Value, inspect::Value> =
        ::std::collections::BTreeMap::new();
    for (k, v) in out_map.into_iter() {
        ret_map.insert(k, v);
    }
    (name, inspect::Value::Map(ret_map))
}
